  type: "choropleth",
  locationmode: "ISO-3",
  locations: data.iso3_codes,
  z: data.color,
  colorscale: [[0, "#EAEAEA"], [1, "#FFB6C1"]],
  zmin: 0,
  zmax: 1,
  showscale: false
};
const layout = {
  title: {
    text: data.title,
    font: { size: 20 }
  },
  geo: {
    projection: { type: "natural earth" },
    showland: true,
    landcolor: "#EAEAEA",
    showcountries: true
  },
  margin: { l: 0, r: 0, t: 40, b: 0 }
};
Plotly.newPlot("map-leo", [trace], layout);
</script>



